c.python:
class Solution:
    def totalTime(self, n: int, requests: list[int]) -> int:
        cur = time = 0
        for r in requests:
            time += abs(cur - r)
            cur = r
        return time

c.cpp:
class Solution {
public:
    int totalTime(int n, vector<int>& requests) {
        int cur = 0, time = 0;
        for (int r : requests) { time += abs(cur - r); cur = r; }
        return time;
    }
};

